 context=await chromium.launchPersistentContext(path.join(report,'profile'),{executablePath:'E:/ai/.tmp/shiying-browser/chromium-1234/chrome-win64/chrome.exe',channel:'chromium',headless:true,acceptDownloads:true,downloadsPath:path.join(report,'files'),ignoreDefaultArgs:['--disable-extensions'],args:[`--disable-extensions-except=${extension}`,`--load-extension=${extension}`,'--disable-background-networking']});
