 await popup.evaluate(()=>{window.popupNative=[];window.popupPermissions=0;chrome.permissions.request=async()=>{popupPermissions++;return true;};chrome.runtime.sendNativeMessage=async(host,payload)=>{popupNative.push({host,payload});return {ok:true,stage:'confirm'};};});
 await show();await popup.locator('#linkDownloadURL').fill(signed);await popup.locator('#linkUseDesktop').click();await popup.waitForFunction(()=>popupNative.length===1);check((await popup.evaluate(()=>popupNative[0])).payload.url===signed,'manual desktop choice alone requests native handoff');check(await popup.locator('#linkDownload').isHidden(),'successful handoff closes the manual choice sheet');
 await show();await popup.locator('#linkDownloadURL').fill('blob:https://example.test/temporary');await popup.locator('#linkUseDesktop').click();check(await popup.locator('#linkDownloadError').isVisible(),'browser-only temporary URL keeps a clear inline error');check(await popup.evaluate(()=>popupNative.length===1&&popupPermissions===1),'unsupported URL is rejected before native permission or transport');await popup.locator('#linkDownloadCancel').click();
 assert.deepEqual(errors,[]);
